\begin{center}
$\frac{v_1}{v_2}=\frac{q_1}{q_2}\cdot \frac{R_1}{R_2}\cdot \frac{m_2}{m_1}=2\cdot 2\cdot \frac{1}{4}=1$

\end{center}
